"""Rebuild the curated bank from the supplied historical archive.
Usage: python scripts/prepare_bank.py '/path/to/Pruebas de Estado.zip'
Question text is transcribed; minor accents/spacing are normalized. Source keys are read, not inferred.
"""
from pathlib import Path
import json, re, shutil, zipfile, tempfile, sys
import xlrd
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT
source=ROOT/'source-bank'/'Pruebas de Estado'
if len(sys.argv)>1:
 temp=Path(tempfile.mkdtemp(prefix='punto-bank-'))
 with zipfile.ZipFile(sys.argv[1]) as z:
  for info in z.infolist():
   target=(temp/info.filename).resolve()
   if not target.is_relative_to(temp.resolve()): raise ValueError('Unsafe archive path')
  z.extractall(temp)
 source=temp/'Pruebas de Estado'
(OUT/'archive').mkdir(exist_ok=True)
names={'math':'Matemáticas','matematicas':'Matemáticas','lenguaje':'Lenguaje','ingles':'Inglés','biologia':'Biología','quimica':'Química','fisica':'Física','historia':'Historia','geografia':'Geografía','filosofia':'Filosofía','medioambiente':'Medio ambiente','medio ambiente':'Medio ambiente','medio_ambiente':'Medio ambiente','medio_comunicacion':'Medios de comunicación','medios_comunicacion':'Medios de comunicación','medios':'Medios de comunicación','violencia':'Violencia y sociedad','viol soci':'Violencia y sociedad','aleman':'Alemán','frances':'Francés','index':'Índice'}
catalog=[]
for p in sorted(source.rglob('*')):
 if not p.is_file(): continue
 rel=p.relative_to(source)
 dest=OUT/'archive'/rel
 dest.parent.mkdir(exist_ok=True,parents=True)
 shutil.copyfile(p,dest)
 if p.suffix.lower()!='.pdf':continue
 stem=p.stem
 prof=stem.startswith(('prof','prfo'))
 plain=re.sub(r'^(prof|prfo)\s*','',stem)
 subject=names.get(plain,stem.replace('AC_EP_','').replace('_2010_Liberadas','').replace('_2010-1','').replace('_2010','').replace('_',' ').title())
 catalog.append({'id':str(rel),'period':rel.parts[0],'subject':subject,'advanced':prof,'title':subject+(' · Profundización' if prof else ''),'url':'archive/'+str(rel),'bytes':p.stat().st_size})
w=xlrd.open_workbook(source/'2005-1/respuestas.xls')
keys={}
for si in [0,1]:
 s=w.sheet_by_index(si)
 for i in range(s.nrows):
  row=s.row_values(i)
  if si==1 and i>16:break
  if isinstance(row[0],float) and re.fullmatch(r'[A-D](?:\s*-\s*[A-D])?',str(row[1]).strip()):
   n=int(row[0]);keys[n]={'answers':re.findall('[A-D]',row[1]),'topic':row[2].strip(),'competency':row[3].strip(),'keyRow':i+1,'keySheet':s.name}
qs=[]
def q(n,file,area,page,title,prompt,options,explanation,context=None,table=None,image=None):
 assert n in keys,n
 assert len(options)==4,n
 key=keys[n]
 item={'id':f'icfes-2005-1-{file}-{n}','number':n,'area':area,'discipline':names.get(file,file),'period':'2005-1','page':page,'title':title,'prompt':prompt,'options':options,'answers':key['answers'],'explanation':explanation,'topic':key['topic'],'competency':key['competency'],'source':f'archive/2005-1/{file}.pdf','answerSource':'archive/2005-1/respuestas.xls','keyRow':key['keyRow'],'keySheet':key['keySheet']}
 if context:item['context']=context
 if table:item['table']=table
 if image:item['image']=image
 qs.append(item)
poem={'title':'Arte poética','body':'Que el verso sea como una llave\nque abra mil puertas.\nUna hoja cae; algo pasa volando;\ncuanto miren los ojos creado sea,\ny el alma del oyente quede temblando.\n\nInventa mundos nuevos y cuida tu palabra;\nel adjetivo, cuando no da vida, mata.\nEstamos en el ciclo de los nervios.\nEl músculo cuelga,\ncomo recuerdo, en los museos;\nMas no por eso tenemos menos fuerza:\nel vigor verdadero reside en la cabeza.\n\nPor qué cantáis la rosa, ¡oh Poetas!\nhacedla florecer en el poema;\nSólo para nosotros\nviven todas las cosas bajo el Sol.\nEl poeta es un pequeño Dios.','citation':'Vicente Huidobro, El espejo de agua, 1916. Reproducido en el cuadernillo de Lenguaje, 2005-1.','verse':True}
q(1,'lenguaje','lectura',1,'La función de la escritura poética','El propósito principal del texto Arte poética es',['comparar la poesía con otras formas artísticas.','enumerar los elementos de la escritura poética.','exponer características universales de la poesía.','establecer la función de la escritura poética.'],'Las órdenes «Inventa mundos nuevos» y «cuida tu palabra» proponen qué debe hacer el poeta. El texto define la función de la escritura poética, más que enumerar recursos o comparar artes.',poem)
q(2,'lenguaje','lectura',1,'Crear con las palabras','En el verso «cuanto miren los ojos creado sea», se quiere dar a entender que la función del poeta consiste en',['inventar el mundo de forma asombrosa.','describir objetivamente lo que observa.','retratar la naturaleza mediante palabras.','explicar lo observado de manera poética.'],'La clave está en «creado»: el poeta inventa un mundo mediante el lenguaje. Las alternativas que se limitan a describir o retratar no recogen esa idea central.',poem)
q(3,'lenguaje','lectura',1,'El poder de un adjetivo','Teniendo en cuenta el sentido global del texto, se puede afirmar que el verso «el adjetivo, cuando no da vida, mata» sugiere que la función de la palabra poética es',['generar vida con su expresión.','aniquilar la imaginación.','ocultar la realidad existente.','hacer aflorar el inconsciente.'],'El poema pide que las palabras creen y den vida. «Mata» expresa el efecto de una palabra que no cumple esa función creadora.',poem)
q(4,'lenguaje','lectura',1,'El poeta como creador','Según el texto Arte poética, «El poeta es un pequeño Dios», porque',['habita un mundo ultraterreno.','determina el destino humano.','crea mundos con la palabra.','domina a otros mediante palabras.'],'La comparación alude a la creación: así como un dios crea, el poeta construye mundos con palabras. No se atribuye al poeta poder sobre el destino de otras personas.',poem)
q(5,'lenguaje','lectura',1,'Reconocer el creacionismo','Teniendo en cuenta el texto Arte poética, se puede afirmar que este pertenece al movimiento de vanguardia denominado',['Futurismo, porque el poeta declara su adhesión al progreso.','Ultraísmo, porque propone una poética fundada en la abundancia de metáforas.','Dadaísmo, porque cimienta su poética en la conjunción fortuita de imágenes dispares.','Creacionismo, porque el poeta declara su independencia de la naturaleza.'],'La invitación a hacer florecer la rosa en el poema, en vez de copiarla, muestra la autonomía creadora de la poesía. Esa propuesta corresponde al creacionismo.',poem)
q(6,'lenguaje','lectura',2,'Inventar una naturaleza','Teniendo en cuenta el texto de Huidobro y los conocimientos acerca del Romanticismo, se puede afirmar que los vanguardistas se distinguen de los románticos en cuanto',['presentan en el poema una copia de la naturaleza.','hacen del poema una naturaleza inventada.','muestran el poema como naturaleza muerta.','plasman en el poema la naturaleza tal cual.'],'En la oposición planteada por este ítem, la propuesta vanguardista del poema consiste en inventar una naturaleza propia. Busca la opción que expresa creación en lugar de copia.',poem)
tram={'title':'El tranvía','body':'Se anunció que São Paulo iba a tener tranvías eléctricos. Los tímidos vehículos tirados por burros, que cortaban la modorra de la ciudad provinciana, iban a desaparecer para siempre. Nunca más veríamos, en la bajada de la ladera de San Antonio, frente a nuestra casa, el tranvía bajar solo, equilibrado por el volante del conductor. Y el par de burros siguiéndolo. Una fiebre de curiosidad tomó las familias, las casas, los grupos. ¿Cómo serían los nuevos tranvías que andaban mágicamente, sin impulso exterior? Yo tenía noticias, por el negrito Lázaro, hijo de la cocinera de mi tía, venida de Río, que era muy peligroso ese asunto de la electricidad. Quien pusiese los pies en las vías se quedaría allí pegado o sería destrozado fatalmente por el tranvía... Un amigo de casa informaba: El tranvía puede andar hasta a velocidades de nueve puntos. Pero ahí se produce una disparada de todos los diablos. Nadie aguanta. ¡Es capaz de saltar de las vías! Y matar a todo el mundo... La ciudad adquirió el aspecto de revolución. Todos se conmovían, intentaban ver. Y los más aventurados querían llegar hasta la temeridad de entrar en el tranvía, ¡hasta andar en el tranvía eléctrico!','citation':'Oswald de Andrade, fragmento reproducido en el cuadernillo de Lenguaje, 2005-1. Se conserva el lenguaje del documento histórico.'}
q(7,'lenguaje','lectura',2,'Una ciudad ante el cambio','En el texto El tranvía, el propósito principal es mostrar',['los beneficios de la energía eléctrica.','el encanto de los vehículos de tracción animal.','la reacción popular frente al progreso.','las tradiciones culturales de la provincia brasileña.'],'El relato se centra en la curiosidad, el temor y las conjeturas de los habitantes ante el tranvía eléctrico. Esas reacciones organizan todo el fragmento.',tram)
q(9,'lenguaje','lectura',2,'Una expresión en contexto','En la expresión «Los tímidos vehículos tirados por burros, que cortaban la modorra de la ciudad provinciana, iban a desaparecer para siempre», la expresión «cortaban la modorra de la ciudad provinciana» se refiere al',['tamaño de São Paulo.','ritmo de vida de São Paulo.','clima de São Paulo.','transporte de São Paulo.'],'«Modorra» sugiere quietud y somnolencia. En el contexto describe el ritmo tranquilo de la vida de la ciudad, interrumpido por el paso de los vehículos.',tram)
q(10,'lenguaje','lectura',3,'Interpretar lo desconocido','Partiendo de la pregunta «¿Cómo serían los nuevos tranvías que andaban mágicamente, sin impulso exterior?», podemos decir que en São Paulo la gente asumió la llegada del vehículo con mentalidad',['científica, porque buscaron explicar racionalmente lo desconocido.','supersticiosa, porque asignaron valor sobrenatural a lo desconocido.','poética, porque usaron la imaginación para entender lo desconocido.','religiosa, porque ubicaron la presencia de Dios en lo desconocido.'],'La palabra «mágicamente» y los temores infundados atribuyen un poder sobrenatural a una tecnología desconocida. El texto no presenta una explicación científica ni una intervención divina.',tram)
q(11,'lenguaje','lectura',3,'Inferir a partir del relato','Del texto El tranvía puede inferirse que São Paulo era, en ese entonces, una ciudad',['premoderna.','renacentista.','postmoderna.','medieval.'],'Según el contraste del relato, la ciudad aún conserva un ritmo provinciano y observa con asombro una innovación moderna. «Premoderna» es la caracterización que recoge ese contraste.',tram)
q(12,'lenguaje','lectura',3,'Elegir un titular','Si el anuncio de la llegada del tranvía fuera un artículo periodístico, podría titularse',['«Llegó el tranvía eléctrico a la ladera de San Antonio».','«Tranvía eléctrico reemplazará al tranvía de burros».','«Tranvía de burros será rival del tranvía eléctrico».','«Así fue el primer día del tranvía eléctrico en São Paulo».'],'El fragmento anuncia un reemplazo futuro: los tranvías eléctricos sustituirán a los vehículos tirados por burros. La opción B conserva tanto el hecho como su tiempo verbal.',tram)
lottery={'title':'La minilotería de Federico','body':'Federico fue el ganador de $100.000 en una minilotería. Por un costo de $1.000 apostó a tres dígitos diferentes y ganó porque los dígitos que seleccionó coincidieron con los sorteados (no importaba el orden).'}
q(13,'math','matematicas',1,'Contar las posibilidades','Federico desea apostar nuevamente utilizando únicamente el dinero que ganó. Si no puede apostar más de una vez a cada trío de dígitos, es correcto afirmar que si invierte los $100.000',['incrementará sus ganancias.','existe una posibilidad entre seis de que pierda.','puede apostar a todos los tríos de dígitos posibles.','existen cinco posibilidades entre seis de que pierda.'],'Con los diez dígitos hay 10 × 9 × 8 / 6 = 120 tríos distintos sin importar el orden. Puede comprar 100 apuestas. Quedan 20 tríos sin cubrir: 20/120 = 1/6 de probabilidad de perder.',lottery)
q(14,'math','matematicas',1,'Comparar dos sorteos','Si Federico decide apostar los $100.000 en el chance y le pagan $500 por cada $1 apostado, pero para ganar debe acertar en su orden los tres últimos dígitos de una lotería, es correcto afirmar que',['si en el chance apuesta $100 a cada trío posible, gana $100.000.','en el chance para ganar $100.000 tiene que apostar mínimo $200.','si en la minilotería apuesta $50.000 es seguro que gana $100.000.','en la minilotería el número de posibles apuestas es menor que en el chance.'],'En la minilotería hay 120 combinaciones de tres dígitos diferentes sin orden. En el chance hay 1.000 secuencias desde 000 hasta 999. Por eso la minilotería ofrece menos apuestas posibles.',lottery)
pool={'title':'El diseño de una piscina','body':'Se quiere construir una piscina rectangular para niños de 4 m de largo, 3 m de ancho y 90 cm de profundidad. Las medidas corresponden al dibujo del cuadernillo original.'}
q(17,'math','matematicas',1,'Baldosas sin desperdicio','Para cubrir todas las paredes de la piscina con baldosas rectangulares del mismo tamaño y evitar desperdicios de material, debería usarse la baldosa representada en',['15 cm × 30 cm.','25 cm × 25 cm.','20 cm × 30 cm.','30 cm × 30 cm.'],'Coloca el lado de 30 cm en vertical: 90/30 = 3 filas. El lado de 20 cm cabe un número entero de veces en los dos largos: 300/20 = 15 y 400/20 = 20. Así se cubren todas las paredes sin cortes.',pool,image={'url':'assets/pool.svg','alt':'Piscina rectangular: largo 4 metros, ancho 3 metros y profundidad 90 centímetros.'})
q(18,'math','matematicas',2,'Volumen y capacidad','Un instructor sabe que cada niño debe contar como mínimo con 1 m³. Si llegan 30 niños, el instructor deberá trabajar máximo con',['10 niños al mismo tiempo, dentro de la piscina.','12 niños al mismo tiempo, dentro de la piscina.','15 niños al mismo tiempo, dentro de la piscina.','20 niños al mismo tiempo, dentro de la piscina.'],'Convierte 90 cm a 0,9 m. El volumen es 4 × 3 × 0,9 = 10,8 m³. Con un mínimo de 1 m³ por niño caben 10 niños completos, sin superar la capacidad indicada.',pool,image={'url':'assets/pool.svg','alt':'Piscina de 4 metros por 3 metros y 0,9 metros de profundidad.'})
savings={'title':'El dinero de Camilo','body':'Camilo ganó $1.600.000 en una rifa y no ha decidido si gastar ese dinero o invertirlo en una entidad financiera que paga 10 % de interés anual sobre el dinero que tenga invertido.'}
q(19,'math','matematicas',2,'La mitad cada semana','Si Camilo guarda el dinero en su casa y gasta cada semana la mitad de lo que le queda, la expresión que representa el dinero que le queda al finalizar la séptima semana es',['(1/2) × 1.600.000','(1/2) × 1.600.000 × 7','(1/2⁶) × 1.600.000','(1/2⁷) × 1.600.000'],'Cada semana queda la mitad del saldo anterior. Después de siete semanas el saldo inicial se multiplica por (1/2) siete veces: 1.600.000 / 2⁷ = 12.500.',savings)
q(20,'math','matematicas',2,'Comprender el interés compuesto','Si Camilo invierte todo el dinero y no hace retiros, transcurridos n años la cantidad de dinero que tiene en el banco está representada por',['1.600.000 × (1/10)ⁿ','1.600.000 × (11/10)ⁿ','1.600.000 + n/10','1.600.000 + 1.600.000 × n/10'],'Cada año se conserva el capital y se añade un 10 % del saldo: se multiplica por 1,1 = 11/10. Tras n años ese factor aparece elevado a n.',savings)
digits={'title':'Contar dígitos, no números','body':'Un profesor propone contar todos los dígitos escritos en los números de 1 a 999. Por ejemplo, de 8 a 13 hay 10 dígitos: 8, 9, 10, 11, 12 y 13. Da como información que de 1 a 99 hay 189 dígitos.\n\nÍtem histórico tipo X: el documento de claves acepta dos alternativas. Selecciona solo una.'}
q(21,'math','matematicas',3,'Un procedimiento eficiente','Si el procedimiento debe ser rápido y confiable, ¿cuál escogería?',['Contar de 1 en 1 hasta llegar a 999.','Contar de 1 a 9, de 10 a 99 y de 100 a 999 y sumar la cantidad obtenida en cada grupo contado.','Contar cuántos números hay con 1, 2 y 3 dígitos; multiplicar por 1, 2 y 3 respectivamente y sumar.','Contar cuántos números hay desde 100 hasta 999, multiplicar por 3 y sumar la cantidad de dígitos de 1 a 99.'],'La clave acepta C y D. Hay 9 números de un dígito, 90 de dos y 900 de tres: 9 + 180 + 2.700 = 2.889. También se puede sumar el dato 189 a 900 × 3.',digits)
q(22,'math','matematicas',3,'¿Se repite igual cada dígito?','Daniel afirma que cada dígito se repite la misma cantidad de veces en los números de 1 a 999. Su compañero dice que es falso porque',['los números tienen un orden, pero sus dígitos no pueden repetirse la misma cantidad de veces.','el conteo se hace desde 1 y no desde cero, teniendo al cero mínimo una vez menos.','la cantidad de números de 2 dígitos es distinta a la de números de 1 dígito.','la cantidad de veces que se repite el cero no es la misma que la de los demás dígitos.'],'La clave acepta B y D. Sin escribir ceros a la izquierda, el 0 no aparece en la primera posición de un número. Por eso su frecuencia difiere de la de los dígitos del 1 al 9.',digits)
q(23,'math','matematicas',3,'El signo y los dígitos','¿Es posible saber cuántos dígitos hay desde −999 hasta −1 conociendo la cantidad que hay de 1 a 999, sin contar de 1 en 1?',['No, porque el conteo solo es posible de manera ascendente, desde 1 hasta 999.','Sí, porque aunque esté antecedido por el signo menos no afecta el conteo de dígitos.','Sí, porque el orden y el signo no se involucran en el conteo: es el mismo número de dígitos.','No, porque los dígitos son siempre positivos, entonces −1 no es un dígito.'],'La clave acepta B y C. A cada número positivo le corresponde uno negativo con las mismas cifras. El signo menos no es un dígito, de modo que el total de dígitos es igual.',digits)
q(24,'math','matematicas',3,'Un intervalo de tres cifras','¿Cómo encontrar cuántos dígitos hay de 403 a 702?',['Escribir los números de 403 a 702 y contar los dígitos de cada uno.','Restar 402 de 702 y multiplicar el resultado por 3.','Contar cuántos números hay desde 403 hasta 702 y multiplicar por 3.','Sumar 702 con 403, multiplicar por 3 y restarlo de los dígitos de 1 a 999.'],'La clave acepta B y C. El intervalo inclusivo contiene 702 − 403 + 1 = 300 números. Todos tienen tres dígitos: 300 × 3 = 900.',digits)
q(26,'biologia','ciencias',1,'El recorrido de una proteína','En una célula animal participan: 1. Retículo endoplásmico rugoso; 2. Ribosoma; 3. Aparato de Golgi; 4. Membrana celular; 5. ARN; 6. ADN. Para producir y secretar una proteína, la secuencia correcta es',['6, 5, 2, 3, 1, 4','6, 5, 1, 2, 3, 4','6, 5, 2, 1, 3, 4','6, 5, 3, 2, 1, 4'],'La información del ADN pasa al ARN. Los ribosomas traducen la proteína, que sigue la vía del retículo endoplásmico rugoso y del Golgi hasta liberarse por la membrana celular.')
q(27,'biologia','ciencias',1,'La comunicación entre neuronas','Un neurotransmisor producido por una neurona altera la actividad de otra célula mediante receptores de membrana específicos. Su función puede verse alterada cuando',['la neurona presináptica no tiene receptores para un neurotransmisor producido por la postsináptica.','la neurona postsináptica tiene mayor variedad de proteínas de membrana que la presináptica.','la neurona presináptica produce neurotransmisores que no interactúan químicamente con las proteínas de membrana de la postsináptica.','la neurona postsináptica y la presináptica tienen el mismo tipo de receptores de membrana.'],'Para transmitir la señal, el neurotransmisor debe unirse a su receptor en la célula postsináptica. Sin esa interacción específica, la señal no produce el efecto esperado.')
q(29,'biologia','ciencias',2,'Regular la acidez digestiva','La gastrina estimula ácido clorhídrico en el estómago y la secretina estimula bicarbonato del páncreas, que neutraliza el ácido en el duodeno. Si el pH del duodeno es 2,5, se esperaría una respuesta de',['disminuir la gastrina y la secretina.','elevar la gastrina y disminuir la secretina.','elevar la gastrina y la secretina.','disminuir la gastrina y aumentar la secretina.'],'Un pH de 2,5 indica un medio muy ácido. La respuesta descrita en el problema requiere reducir la estimulación del ácido y aumentar el bicarbonato que lo neutraliza.')
plants={'title':'Nutrición y crecimiento','body':'Un investigador siembra siete plántulas de la misma especie y peso inicial similar. Una recibe nutrientes completos y las otras carecen de uno. Después de unas semanas se mide el peso final.'}
planttable={'headers':['Tratamiento','Peso final (g)'],'rows':[['Completo','6,2'],['Sin azufre','6,1'],['Sin zinc','7,3'],['Sin magnesio','3,7'],['Sin aluminio','5,8'],['Sin manganeso','4,2'],['Sin potasio','3,9']]}
q(30,'biologia','ciencias',2,'Identificar una variable clave','Según estos resultados, el elemento más importante para el crecimiento de esta planta es el',['magnesio.','azufre.','manganeso.','zinc.'],'En esta experiencia, la planta sin magnesio tiene el menor peso final: 3,7 g. Su ausencia se asocia con la mayor reducción del crecimiento entre los tratamientos comparados. La conclusión se limita a estos datos.',plants,planttable)
q(31,'biologia','ciencias',2,'Proponer una hipótesis','Una solución completa no garantiza el mayor crecimiento observado. De acuerdo con los datos, se podría proponer que',['la solución completa carece de otros nutrientes fundamentales.','el potasio hace que la planta crezca más rápido.','el zinc inhibe el crecimiento de la planta.','el manganeso podría excluirse de la solución completa.'],'La planta sin zinc llega a 7,3 g, frente a 6,2 g con solución completa. Los datos apoyan como hipótesis que, en estas condiciones, el zinc inhibe el crecimiento; no demuestran que ocurra en todas las plantas.',plants,planttable)
q(33,'biologia','ciencias',3,'Interrumpir la especiación','Una barrera geográfica dividió una población de iguanas hace cientos de años. Siguen siendo la misma especie, aunque han surgido diferencias morfológicas. Para evitar que avance la especiación, es necesario que entre ellas se',['establezca competencia por el espacio.','promueva el intercambio de genes por reproducción.','desarrolle cooperación para adquirir alimento.','lleve a cabo depredación por sobrepoblación.'],'La reproducción entre ambas poblaciones restablece el flujo génico. Ese intercambio contrarresta la divergencia genética causada por su aislamiento.')
q(38,'quimica','ciencias',1,'Estructura y ebullición','La tabla muestra tres compuestos orgánicos. A partir de estos datos es válido afirmar que',['el punto de ebullición solo depende del número de carbonos.','a mayor número de ramificaciones menor es el punto de ebullición.','el punto de ebullición de los isómeros de un alcano es el mismo.','a mayor número de ramificaciones mayor es el punto de ebullición.'],'Los tres compuestos son isómeros con cinco carbonos. En la tabla, la temperatura disminuye desde 36,5 °C hasta 9,8 °C al aumentar la ramificación. Compara primero las estructuras y luego la tendencia.',table={'headers':['Compuesto','Ebullición (°C)'],'rows':[['n-pentano','36,5'],['2-metilbutano','27,85'],['2,2-dimetilpropano','9,8']]})
boil={'title':'Cuatro líquidos a 1 atm','body':'La tabla presenta las temperaturas de ebullición a una atmósfera de presión.'}
boiltable={'headers':['Líquido','Ebullición (°C)'],'rows':[['Agua','100'],['Éter etílico','34,5'],['Metanol','65'],['Benceno','80,1']]}
q(40,'quimica','ciencias',2,'Comparar la presión de vapor','Según los datos, a 25 °C el líquido con mayor presión de vapor es el',['agua.','éter etílico.','metanol.','benceno.'],'Entre estos líquidos, el de menor punto de ebullición es el más volátil y tiene mayor presión de vapor a 25 °C. El éter etílico hierve a 34,5 °C.',boil,boiltable)
q(41,'quimica','ciencias',2,'Predecir el estado físico','A 70 °C y 1 atm, las sustancias que permanecen en estado líquido son',['metanol y agua.','benceno y éter etílico.','benceno y agua.','metanol y éter etílico.'],'70 °C está por debajo de los puntos de ebullición del benceno (80,1 °C) y el agua (100 °C). En cambio, supera los del metanol y del éter etílico.',boil,boiltable)
q(42,'quimica','ciencias',2,'Leer una concentración','La etiqueta de un vinagre dice «solución de ácido acético al 4 % en peso». Esto indica que contiene',['4 g de ácido acético en 96 g de solución.','100 g de soluto y 4 g de ácido acético.','100 g de solvente y 4 g de ácido acético.','4 g de ácido acético en 100 g de solución.'],'El porcentaje en masa es masa de soluto / masa de solución × 100. Por tanto, el 4 % corresponde a 4 g de ácido acético por cada 100 g de solución total.')
q(46,'quimica','ciencias',3,'Lluvia ácida y pH','Un tanque contiene agua de pH 7. Cae una cantidad de lluvia ácida que modifica su pH. El pH de la solución resultante',['aumenta, porque aumenta [H⁺].','aumenta, porque disminuye [H⁺].','disminuye, porque aumenta [H⁺].','disminuye, porque disminuye [H⁺].'],'El pH se relaciona inversamente con la concentración de iones hidrógeno: pH = −log₁₀[H⁺]. Al aportar ácido aumenta [H⁺] y disminuye el pH.')
q(48,'quimica','ciencias',3,'Añadir una base fuerte','Se tienen 1.000 ml de una solución 0,5 M de KOH con pH 13,7. Si se adiciona 1 mol de KOH, es muy probable que',['permanezca constante la concentración.','aumente la concentración de iones [OH⁻].','permanezca constante el pH.','aumente la concentración de iones [H⁺].'],'El KOH es una base fuerte y aporta iones OH⁻ al disolverse. Añadirlo a la solución, en las condiciones del enunciado, aumenta la concentración de esos iones.')
q(54,'fisica','ciencias',2,'Ebullición y cantidad de agua','A recipientes iguales con 1, 2 y 3 litros de agua se les suministra calor hasta hervir. La temperatura de ebullición es',['igual en los tres recipientes.','mayor en el de 1 litro.','mayor en el de 3 litros.','menor en el de 3 litros.'],'Para la misma sustancia y presión, la temperatura de ebullición no depende de la cantidad de agua. Una mayor cantidad requiere más energía, pero no una temperatura de ebullición mayor.')
q(55,'fisica','ciencias',2,'Energía para calentar agua','Tres recipientes iguales contienen 1, 2 y 3 litros de agua a la misma temperatura inicial. El calor absorbido hasta alcanzar la ebullición es',['el mismo en los tres recipientes.','dependiente del volumen de agua e independiente de la temperatura inicial.','dependiente del volumen de agua y de la temperatura inicial.','directamente proporcional al volumen del recipiente.'],'Antes de hervir, Q = m c ΔT. La masa depende del volumen de agua y ΔT depende de la temperatura inicial. El volumen del recipiente no determina por sí solo el calor necesario.')
q(56,'fisica','ciencias',3,'Frecuencia y número de ondas','Un flautista toca durante 5 segundos una nota cuya frecuencia es 55 Hz. El número de longitudes de onda que emite en ese tiempo es',['275','11','66','30'],'Una frecuencia de 55 Hz representa 55 ciclos por segundo. En 5 segundos se emiten 55 × 5 = 275 ciclos completos.')
waves={'title':'Ondas en una piscina','body':'Una persona deja caer esferas periódicamente sobre un punto de la superficie de una piscina. Después de 2 s se han formado 20 frentes de onda y su rapidez de avance es de 10 m/s.'}
q(57,'fisica','ciencias',3,'Contar frentes de onda','0,2 s después de arrojar la primera esfera, la cantidad de frentes de onda que observa es',['0','2','10','0,1'],'El modelo del ítem da una frecuencia de 20/2 = 10 frentes por segundo. En 0,2 segundos se producen 10 × 0,2 = 2 frentes de onda.',waves)
q(58,'fisica','ciencias',3,'Calcular una longitud de onda','La longitud de onda de estas perturbaciones es',['100 m.','20 m.','5 m.','1 m.'],'La frecuencia es 10 Hz y la rapidez 10 m/s. Con v = λ f, la longitud de onda es λ = 10/10 = 1 m.',waves)
q(59,'fisica','ciencias',3,'¿Qué expresa un voltaje?','Una pila indica 1,5 voltios. Si 1 voltio = 1 joule/coulomb, 1,5 voltios significa que',['la energía por unidad de carga es 1,5 joules.','la energía total acumulada en la pila es 1,5 joules.','la energía máxima que puede proporcionar la pila es 1,5 joules.','la energía por electrón es 1,5 joules.'],'El voltaje expresa energía transferida por carga: 1,5 J por cada coulomb. La opción A es la clave del cuadernillo; «unidad de carga» se interpreta como un coulomb, no un electrón.')
q(60,'fisica','ciencias',3,'Un circuito interrumpido','En un circuito en serie de tres bombillos, uno se funde. La corriente en los otros dos',['aumenta, porque disminuye la resistencia.','disminuye, porque parte de la corriente se pierde donde se fundió el bombillo.','permanece igual, porque no depende de la resistencia.','es nula, porque la corriente no circula.'],'Un circuito en serie tiene un único camino para la corriente. Si el filamento de un bombillo se rompe, abre ese camino y deja de circular corriente por todos.')
q(61,'historia','sociales',1,'Una tradición religiosa','La Santería se constituyó en una religión ampliamente practicada en Cuba, especialmente después del triunfo de la Revolución. Reúne creencias africanas con santos y ritos católicos. Según el planteamiento histórico del ítem, su predominio se explica porque',['las prácticas tradicionales africanas se vieron liberadas de la presión católica.','la revolución impulsó las creencias populares contra el credo católico.','la revolución cubana prohibió la existencia de instituciones religiosas.','la Iglesia católica impulsó desde la colonia el sincretismo religioso.'],'La clave A se centra en un cambio de las condiciones para practicar tradiciones africanas. El ítem no permite deducir una prohibición total de instituciones religiosas. La formulación se conserva como ejercicio histórico, no como diagnóstico religioso actual.')
q(62,'historia','sociales',1,'Unificar el poder político','En Mesopotamia se desarrollaron ciudades como Ur y Uruk. Al unificarse políticamente y concentrar el poder en un rey, se posibilita',['una organización política homogénea para las dos ciudades.','concentrar en una ciudad todas las labores administrativas.','administrar justicia según los deseos del monarca.','concentrar en la familia real los poderes político, religioso y administrativo.'],'Compartir una autoridad política hace posible una organización común. Las demás opciones agregan consecuencias específicas que no se desprenden necesariamente de la unificación.')
q(63,'historia','sociales',1,'Ejércitos tras la independencia','Los ejércitos sirven para defensa y ataque y requieren mando, organización y disciplina. Tras la independencia de España, las antiguas colonias necesitaron ejércitos especialmente para',['contrarrestar el predominio militar de Estados Unidos.','rechazar ataques de piratas en el Caribe.','repeler un posible ataque español para recuperar las colonias.','garantizar la soberanía y autonomía territorial, en el interior y en las fronteras.'],'La soberanía y la autonomía abarcan la defensa frente a amenazas externas y el control del territorio. La opción D expresa una función más completa que una amenaza particular.')
q(64,'historia','sociales',1,'El alcance de la industrialización','La Revolución Industrial reorganizó el trabajo, concentró trabajadores en fábricas, introdujo tecnologías y usó el ferrocarril para agilizar el comercio. De esto se infiere que',['generó nuevas clases sociales como burguesía y proletariado.','limitó la economía a bienes manufacturados.','acabó definitivamente con las formas tradicionales de producción.','transformó la economía desde la producción hasta la circulación de bienes.'],'El enunciado incluye cambios en las fábricas y en el transporte comercial. La opción D reúne ambas dimensiones: producir bienes y hacerlos circular.')
q(65,'historia','sociales',1,'Interpretar una relación económica','En los años setenta, la caída de exportaciones redujo el ingreso de dólares en Latinoamérica. Colombia, Bolivia y Perú se vieron menos afectados por ingresos del narcotráfico. Según ese análisis, el menor impacto se explica porque',['la expansión cafetera colombiana estimuló el ingreso ilegal de dólares.','los ingresos del narcotráfico compensaron pérdidas de otros sectores.','la inflación estadounidense afectó la balanza comercial de Latinoamérica.','todas las transacciones del narcotráfico se hacen en dólares.'],'La relación propuesta es de compensación: una fuente adicional de divisas reduce parcialmente el efecto de pérdidas en otras actividades. No supone aprobar ni minimizar los daños del narcotráfico.')
q(66,'historia','sociales',2,'Distinguir criterios de desigualdad','En la colonia, el prestigio social se relacionaba con el origen familiar y el color de piel. ¿Qué decisión NO obedece a un criterio de diferenciación racial?',['Un criollo es nombrado en un alto cargo de la audiencia.','Un blanco pobre solicita beca para estudiar en el principal colegio.','Se funda una universidad para indígenas con apoyo de la Corona.','Un aspirante a profesor es rechazado por su origen mestizo.'],'La solicitud de beca se explica por la condición económica, expresada en «pobre». Las otras situaciones sí aluden al origen racial o a instituciones diferenciadas por ese criterio.')
q(67,'historia','sociales',2,'Normas y control social','En la sociedad colonial, el matrimonio y las «buenas costumbres» promovían autocontrol y vigilancia de las relaciones de otras personas. Este comportamiento evidencia',['el afán judicial de mantener el orden.','que las uniones prohibidas generan permisividad clandestina.','la necesidad de la Iglesia de perseguir esposos infieles.','que una sociedad estática crea una reglamentación social conservadora.'],'La vigilancia colectiva de costumbres y relaciones protege el orden social establecido. La clave D interpreta el conjunto como una reglamentación conservadora de la vida social.')
q(68,'historia','sociales',2,'Una causa de la independencia','Germán Arciniegas plantea que los cabildos de 1810 surgieron de protestas populares y que sus líderes estaban influidos por la Ilustración y el Romanticismo. La causa principal de este proceso se encuentra en',['el sistema colonial, que había creado profundas rupturas sociales e inconformismo.','las ideas ilustradas que ofrecían modelos militares europeos.','la mala administración de funcionarios de la Corona.','la gran cantidad de impuestos exigidos por España.'],'La opción A relaciona el sistema colonial con un malestar social amplio. La administración y los impuestos pueden contribuir, pero son causas más parciales que la estructura descrita.')
q(69,'historia','sociales',2,'Inversión y desigualdad regional','La industrialización europea impulsó inversiones en regiones latinoamericanas productoras de materias primas. Algunas crecieron y otras quedaron marginadas porque',['la élite terrateniente se negó a invertir por afecto a la tierra.','la tecnología de comunicaciones impedía crear cualquier red vial amplia.','faltaban infraestructura de comunicaciones y voluntad política para distribuir los beneficios.','los grandes agricultores no querían participar en actividades industriales.'],'La opción C combina una barrera material y una decisión política para explicar por qué los beneficios se concentran. Evita atribuir todo el proceso a una sola motivación personal.')
q(70,'historia','sociales',3,'Leer una imagen del cambio urbano','Un sacerdote siux llamado Babeagua soñó que seres extraños tejían una telaraña alrededor de su pueblo y lo encerrarían en casas grises sobre tierra estéril. Según el ítem, la historia muestra que',['la imagen se acercó a efectos posteriores del desarrollo urbano moderno.','los siux construyeron viviendas grandes y coloridas.','el sacerdote aceptó la superioridad de los blancos.','el sueño probó poderes de clarividencia por ser sacerdote.'],'La clave A interpreta la telaraña y las casas como una imagen de la expansión urbana y sus efectos. El relato no demuestra superioridad de un grupo ni capacidades sobrenaturales.')
q(98,'ingles','ingles',1,'Talking about the past','Two friends were talking about a picnic they had two days before. One of them said to the other:',['See? I tell you it was going to be fun.','See? I told you it is going to be fun.','See? I told you it was going to be fun.','See? I tell you it is going to be fun.'],'La conversación recuerda una predicción pasada sobre un evento que ya ocurrió. «I told you» y «was going to» mantienen esa referencia temporal en el pasado.')
fight={'title':'Complete the story · 105–107','body':'Patrick and Pauline Peters got married six months ago and they are already famous for their fights. Mrs. White, who lives opposite, says: “(105) ____ I asked them nicely to stop fighting because my baby couldn’t get to sleep, but they didn’t. Then my husband knocked at their door and told them to stop. They threw a chair at him. (106) ____, we decided to call the police. Mr. and Mrs. Peters admitted to the police (107) ____ they had been arguing. However, they denied having thrown the chair.”'}
q(105,'ingles','ingles',2,'Sequencing a story','Choose the word that correctly completes blank (105).',['When','Before','First','Thus'],'«First» introduce la primera acción de una secuencia. Más adelante «Then» presenta el paso siguiente.',fight)
q(106,'ingles','ingles',2,'Connecting a consequence','Choose the expression that correctly completes blank (106).',['Therefore','In this respect','In the same way','Besides'],'Llamar a la policía es una consecuencia del episodio anterior. «Therefore» significa «por lo tanto» y establece esa relación.',fight)
q(107,'ingles','ingles',2,'Introducing a reported statement','Choose the word that correctly completes blank (107).',['which','how','what','that'],'«Admitted ... that they had been arguing» introduce lo que la pareja reconoció. «That» funciona como conjunción para la afirmación reportada.',fight)
q(109,'ingles','ingles',3,'Putting a paragraph in order','Karen writes about the Browns, her host family. Put these segments in order:\n1. but it isn’t easy to understand them!\n2. Mr. and Mrs. Brown have three children.\n3. My new address is at the top of the letter. I’m with an English family, the Browns.\n4. Thomas is fourteen, Catherine is twelve, and Andrew is seven. They are very friendly,',['3, 4, 2, 1','4, 2, 3, 1','3, 2, 4, 1','4, 3, 2, 1'],'Primero se presenta a la familia (3), después a sus tres hijos (2), luego sus nombres y edades (4). La conjunción «but» completa la última idea con el segmento 1.')
q(110,'ingles','ingles',3,'Offering help','A relative arrives. Diane says, “What a nice surprise! Please come in.” The relative says, “Thank you.” Diane asks: ____ The relative answers, “Please! They are very heavy.”',['Can I help you with your suitcases?','Must I help you with your suitcases?','Should I help you with your suitcases?','Do I have to help you with your suitcases?'],'«Can I help you ...?» ofrece ayuda de manera natural. La respuesta sobre el peso de las maletas acepta esa oferta; no se trata de preguntar por una obligación.')
q(113,'ingles','ingles',3,'Making a polite request','Mark has a problem with his pen, so he asks his teacher for one. Mark says:',['Could you lend me your pen?','It would be great if you can give me that pen.','I need that pen, please give it to me.','Would you like to give me that pen?'],'«Could you lend me ...?» es una petición cortés y precisa para pedir algo prestado. Las otras alternativas resultan menos adecuadas al contexto o cambian la intención.')
tramp={'title':'The tramp','body':'A tramp was sleeping on a park bench late at night. A man and woman went past. One of them tapped him on the shoulder and asked, “Excuse me! What’s the time?”. The tramp was very annoyed at being woken up. “I don’t know!”, he said angrily. “I don’t have a watch”. And he went back to sleep.\n\nSome time later another man who was passing by woke the tramp up and said, “I’m sorry to bother you, but I wonder if you could tell me what time it is”.\n\nAgain the tramp said that he didn’t know. By now he was very irritated so he got a pen and a piece of paper and wrote “I DON’T KNOW WHAT THE TIME IS” on it, and went back to sleep.\n\nHalf an hour later, a policeman went by. He read the sign, woke the tramp up and said: “It’s 2:30, sir”.','citation':'Cuadernillo histórico de Inglés, 2005-1, página 4.'}
q(118,'ingles','ingles',4,'Understanding the whole story','Based on the text, we can conclude that',['it was an unlucky night for the man.','the man should have had a watch.','the man was finally able to sleep well.','it was a lucky day for the man.'],'El personaje intenta dormir y es despertado varias veces. Incluso el cartel que escribe provoca otra interrupción. Esa secuencia apoya que tuvo una noche desafortunada.',tramp)
q(119,'ingles','ingles',4,'Finding a pronoun’s reference','In “wrote ‘I DON’T KNOW WHAT THE TIME IS’ on it”, the word “it” refers to:',['the watch.','the park bench.','the piece of paper.','the pen.'],'El pronombre «it» retoma «a piece of paper», la superficie sobre la que escribe. Revisa el sustantivo compatible más cercano en la misma oración.',tramp)
q(120,'ingles','ingles',4,'Inferring an intention','“He read the sign, woke the tramp up and said: ‘It’s 2:30, sir’” implies that the policeman',['hated people who sleep on park benches.','didn’t want the man to stay there anymore.','wanted to start a conversation with the man.','thought the tramp wanted to know the time.'],'El policía interpreta «No sé qué hora es» como una necesidad de información. Por eso despierta al hombre para decirle la hora, sin captar que el cartel buscaba evitar interrupciones.',tramp)
assert len(qs)==60,len(qs)
